def inspect_zip(path: Path):

    if not path.is_file():
        return []

    with zipfile.ZipFile(path, mode="r") as archive:

        members = [
            info
            for info in archive.infolist()
            if not info.is_dir()
        ]

    return [
        {
            "name": info.filename,
            "size": info.file_size,
        }
        for info in members
    ]


