print("-" * 78)

try:
    script60_tree = ast.parse(script60_text)
except SyntaxError as exc:
    raise AssertionError(
        f"Could not parse authoritative Notebook 60 script: {exc}"
    )

script60_definitions = []

for node in ast.walk(script60_tree):

    if isinstance(
        node,
        (
            ast.FunctionDef,
            ast.AsyncFunctionDef,
            ast.ClassDef,
        )
    ):
        script60_definitions.append({
            "type":
                "class"
                if isinstance(node, ast.ClassDef)
                else "function",

            "name":
                node.name,

            "line":
                node.lineno,
        })

script60_definitions = sorted(
    script60_definitions,
    key=lambda item: item["line"],
)

print(f"Definitions found: {len(script60_definitions)}")

# Print names likely relevant to inference / simulator integration.

