print("-" * 78)

predict_lines = [
    match["line_number"]
    for match in NOTEBOOK60_MATCHES["predict_proba"]
]

def print_context(lines, center, radius=12):

    start = max(1, center - radius)
    end = min(len(lines), center + radius)

    print(
        f"\n--- lines {start}–{end}; "
        f"match at line {center} ---"
    )

    for line_number in range(start, end + 1):

        marker = ">>" if line_number == center else "  "

        print(
            f"{marker} {line_number:>6}: "
            f"{lines[line_number - 1][:240]}"
        )


for center in predict_lines[:12]:
    print_context(
        script60_lines,
        center,
        radius=12,
    )

