# ------------------------------------------------------------
# 3. Generic source search helper
# ------------------------------------------------------------

def search_source_lines(
    label,
    lines,
    terms,
    max_per_term=25,
):

    print("\n" + "=" * 78)
    print(label)
    print("=" * 78)

    results = {}

    for term in terms:

        matches = []

        for line_number, line in enumerate(
            lines,
            start=1,
        ):

            if term.lower() in line.lower():

                matches.append(
                    (
                        line_number,
                        line.rstrip(),
                    )
                )

        results[term] = matches

        print(f"\nSearch term: {term!r}")
        print(f"Matches    : {len(matches)}")

        for line_number, line in matches[:max_per_term]:

            print(
                f"{line_number:>7}: "
                f"{line[:240]}"
            )

        if len(matches) > max_per_term:

            print(
                f"... {len(matches) - max_per_term} "
                "additional matches"
            )

    return results


