adapter_source = r'''
from __future__ import annotations

import os
from pathlib import Path
from typing import Any, Iterable

import joblib

from cg.api import (
    Observation,
    OptionType,
    SelectContext,
    all_card_data,
    to_observation_class,
)


CERTIFIED_TARGET_CLASSES = [
    "Bite",
    "Flame Tail",
    "Fury Swipes",
    "Quick Attack",
    "Razor Leaf",
    "Scratch",
    "Tackle",
    "Tail Whap",
    "Thunderbolt",
    "Vine Whip",
    "Water Pulse",
]


def _unique_legal_indices(
    ranked_indices: Iterable[int],
    option_count: int,
) -> list[int]:
    """Return unique legal option indices in ranking order."""

    result = []
    seen = set()

    for value in ranked_indices:

        try:
            index = int(value)
        except Exception:
            continue

        if index < 0 or index >= option_count:
            continue

        if index in seen:
            continue

        seen.add(index)
        result.append(index)

    return result


def _enforce_cardinality(
    ranked_indices: Iterable[int],
    option_count: int,
    min_count: int,
    max_count: int,
) -> list[int]:
    """
    Enforce the official selection-cardinality contract.

    Only legal unique indices are returned.
    """

    option_count = max(0, int(option_count))
    min_count = max(0, int(min_count))
    max_count = max(0, int(max_count))

    if option_count == 0:
        return []

    max_allowed = min(
        option_count,
        max_count,
    )

    min_required = min(
        option_count,
        min_count,
        max_allowed,
    )

    ranked = _unique_legal_indices(
        ranked_indices,
        option_count,
    )

    # Fill with remaining legal options only when required.
    if len(ranked) < min_required:

        used = set(ranked)

        for index in range(option_count):

            if index not in used:
                ranked.append(index)
                used.add(index)

            if len(ranked) >= min_required:
                break

    return ranked[:max_allowed]


class CertifiedHybridRouter:
    """
    Final submission router.

    Certified RF:
        tournament-domain attack decisions only.

    Historical policy:
        official non-attack decisions and safe fallback.

    No training.
    No model mutation.
    """

    def __init__(
        self,
        deck: list[int],
        model_path: str | Path,
        historical_router: Any,
        feature_builder: Any,
        attack_option_mapper: Any,
    ) -> None:

        self.deck = list(deck)

        if len(self.deck) != 60:
            raise ValueError(
                f"Expected 60-card deck; got {len(self.deck)}."
            )

        self.model_path = Path(model_path)

        self.model = joblib.load(
            self.model_path
        )

        self.historical_router = historical_router
        self.feature_builder = feature_builder
        self.attack_option_mapper = attack_option_mapper

        model_classes = [
            str(value)
            for value in self.model.classes_
        ]

        if model_classes != CERTIFIED_TARGET_CLASSES:
            raise RuntimeError(
                "Certified model class contract mismatch. "
                f"Observed: {model_classes}"
            )

        if getattr(
            self.model,
            "n_features_in_",
            None,
        ) != 61:
            raise RuntimeError(
                "Certified model feature contract mismatch."
            )

    def _historical_rank(
        self,
        observation: Observation,
    ) -> list[int]:
        """
        Obtain legal-option ranking from the preserved historical router.

        The concrete historical adapter is injected rather than silently
        rewritten here.
        """

        ranked = self.historical_router(
            observation
        )

        if isinstance(ranked, int):
            ranked = [ranked]

        return [
            int(value)
            for value in ranked
        ]

    def _certified_attack_rank(
        self,
        observation: Observation,
    ) -> list[int] | None:
        """
        Rank mapped legal attack options using the frozen certified model.

        Returns None when the official context cannot be mapped safely.
        """

        mapped = self.attack_option_mapper(
            observation
        )

        if not mapped:
            return None

        # Expected mapped record:
        #
        # {
        #     "option_index": int,
        #     "attack_name": str,
        #     "feature_vector": sequence[float] length 61
        # }

        valid_rows = []

        for record in mapped:

            option_index = int(
                record["option_index"]
            )

            attack_name = str(
                record["attack_name"]
            )

            feature_vector = list(
                record["feature_vector"]
            )

            if attack_name not in CERTIFIED_TARGET_CLASSES:
                continue

            if len(feature_vector) != 61:
                raise RuntimeError(
                    "Certified attack feature vector "
                    "must contain exactly 61 features."
                )

            valid_rows.append(
                (
                    option_index,
                    attack_name,
                    feature_vector,
                )
            )

        if not valid_rows:
            return None

        ranked_records = []

        for (
            option_index,
            attack_name,
            feature_vector,
        ) in valid_rows:

            probabilities = self.model.predict_proba(
                [feature_vector]
            )[0]

            class_to_probability = {
                str(class_name): float(probability)
                for class_name, probability
                in zip(
                    self.model.classes_,
                    probabilities,
                )
            }

            probability = class_to_probability.get(
                attack_name,
                0.0,
            )

            ranked_records.append(
                (
                    probability,
                    option_index,
                )
            )

        ranked_records.sort(
            key=lambda item: item[0],
            reverse=True,
        )

        return [
            option_index
            for _, option_index
            in ranked_records
        ]

    def choose(
        self,
        observation: Observation,
    ) -> list[int]:

        # Official deck request.
        if getattr(
            observation,
            "select",
            None,
        ) is None:
            return list(
                self.deck
            )

        select = observation.select

        options = list(
            getattr(
                select,
                "options",
                [],
            )
        )

        option_count = len(
            options
        )

        min_count = int(
            getattr(
                select,
                "minCount",
                1,
            )
        )

        max_count = int(
            getattr(
                select,
                "maxCount",
                1,
            )
        )

        # Attempt certified attack routing first.
        certified_rank = (
            self._certified_attack_rank(
                observation
            )
        )

        if certified_rank is not None:

            # Historical ranking remains available to satisfy any
            # additional required cardinality without inventing indices.
            historical_rank = self._historical_rank(
                observation
            )

            combined_rank = (
                certified_rank
                + historical_rank
            )

            return _enforce_cardinality(
                combined_rank,
                option_count,
                min_count,
                max_count,
            )

        # Non-attack or unmappable context:
        # preserve historical legal-option behavior.
        historical_rank = self._historical_rank(
            observation
        )

        return _enforce_cardinality(
            historical_rank,
            option_count,
            min_count,
            max_count,
        )
'''


