# ------------------------------------------------------------
# 3. Static interface inventory
# ------------------------------------------------------------

print("\n" + "=" * 78)
print("2. CANDIDATE INTERFACE INVENTORY")
print("=" * 78)

INTERFACE_NAMES = {
    "agent",
    "decide",
    "decide_snapshot",
    "choose_action",
    "choose_snapshot_action",
    "rank_legal_actions",
    "choose_best_option_index",
}

candidate_interfaces = {}
candidate_imports = {}
candidate_training_signals = {}

TRAINING_PATTERNS = [
    r"\.fit\s*\(",
    r"fit\s*\(",
    r"train\s*\(",
    r"partial_fit\s*\(",
]

for label, path in candidate_paths.items():

    if not path.is_file():
        continue

    text = path.read_text(
        encoding="utf-8-sig",
        errors="replace",
    ).lstrip("\ufeff")

    try:
        tree = ast.parse(text)
    except Exception as exc:

        candidate_interfaces[label] = {
            "parse_error": str(exc)
        }

        continue

    defs = sorted(
        {
            node.name
            for node in ast.walk(tree)
            if isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                    ast.ClassDef,
                )
            )
        }
    )

    selected_defs = [
        name
        for name in defs
        if name in INTERFACE_NAMES
    ]

    imports = []

    for node in tree.body:

        if isinstance(node, ast.Import):

            imports.extend(
                alias.name
                for alias in node.names
            )

        elif isinstance(
            node,
            ast.ImportFrom,
        ):

            module = node.module or ""

            imports.append(
                module
            )

    training_hits = []

    for pattern in TRAINING_PATTERNS:

        matches = re.findall(
            pattern,
            text,
            flags=re.IGNORECASE,
        )

        if matches:
            training_hits.append(
                {
                    "pattern": pattern,
                    "count": len(matches),
                }
            )

    candidate_interfaces[label] = {
        "definitions":
            selected_defs,

        "all_definition_count":
            len(defs),
    }

    candidate_imports[label] = sorted(
        set(imports)
    )

    candidate_training_signals[label] = (
        training_hits
    )

    print(f"\n{label}")

    print(
        "  Relevant definitions:",
        selected_defs,
    )

    print(
        "  Imports cg:",
        any(
            (
                module == "cg"
                or
                module.startswith("cg.")
            )
            for module in imports
        ),
    )

    print(
        "  Training signals:",
        training_hits,
    )


