def import_inventory(tree):

    imports = []

    for node in tree.body:

        if isinstance(
            node,
            ast.Import,
        ):

            for alias in node.names:

                imports.append(
                    alias.name
                )

        elif isinstance(
            node,
            ast.ImportFrom,
        ):

            imports.append(
                node.module or ""
            )

    return sorted(
        set(imports)
    )


