def definition_inventory(tree):

    records = []

    for node in tree.body:

        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
            )
        ):

            records.append(
                {
                    "name":
                        node.name,

                    "kind":
                        (
                            "class"
                            if isinstance(
                                node,
                                ast.ClassDef,
                            )
                            else
                            "function"
                        ),

                    "line":
                        node.lineno,

                    "end_line":
                        getattr(
                            node,
                            "end_lineno",
                            node.lineno,
                        ),
                }
            )

    return records


