# ------------------------------------------------------------

nb20_top_level_defined_names = set()

for node in nb20_tree.body:

    if isinstance(
        node,
        (
            ast.FunctionDef,
            ast.AsyncFunctionDef,
            ast.ClassDef,
        )
    ):

        nb20_top_level_defined_names.add(
            node.name
        )

    elif isinstance(
        node,
        ast.Assign,
    ):

        for target in node.targets:

            if isinstance(
                target,
                ast.Name,
            ):
                nb20_top_level_defined_names.add(
                    target.id
                )

    elif isinstance(
        node,
        ast.AnnAssign,
    ):

        if isinstance(
            node.target,
            ast.Name,
        ):
            nb20_top_level_defined_names.add(
                node.target.id
            )


