print("=" * 78)


def loaded_names_from_source(
    source
):

    tree = ast.parse(
        source
    )

    loaded = set()
    bound = set()

    for node in ast.walk(
        tree
    ):

        if isinstance(
            node,
            ast.Name,
        ):

            if isinstance(
                node.ctx,
                ast.Load,
            ):
                loaded.add(
                    node.id
                )

            elif isinstance(
                node.ctx,
                (
                    ast.Store,
                    ast.Param,
                )
            ):
                bound.add(
                    node.id
                )

    return sorted(
        loaded - bound
    )


