BUILTIN_NAMES_17C = {
    "Any",
    "Exception",
    "False",
    "None",
    "True",
    "ValueError",
    "bool",
    "dict",
    "enumerate",
    "float",
    "getattr",
    "hasattr",
    "int",
    "len",
    "list",
    "max",
    "min",
    "print",
    "range",
    "set",
    "sorted",
    "str",
    "tuple",
    "type",
    "zip",
}


def external_loaded_names(node):

    loaded = set()
    bound = set()

    for child in ast.walk(node):

        if isinstance(
            child,
            ast.Name,
        ):

            if isinstance(
                child.ctx,
                ast.Load,
            ):
                loaded.add(
                    child.id
                )

            elif isinstance(
                child.ctx,
                (
                    ast.Store,
                    ast.Param,
                )
            ):
                bound.add(
                    child.id
                )

    return (
        loaded
        -
        bound
        -
        BUILTIN_NAMES_17C
    )


