# =============================================================================
# 2. CARDINALITY HELPER
# =============================================================================

def enforce_official_cardinality(
    ranked_indices,
    legal_indices,
    min_count,
    max_count,
):
    """
    Convert a ranked candidate sequence into an official simulator-compatible
    list of unique legal option indices.

    Rules:
      1. Return only legal option indices.
      2. Remove duplicates while preserving ranking order.
      3. Never exceed max_count.
      4. Fill from remaining legal options when required to satisfy min_count.
      5. Never invent an option index.
    """

    legal = []
    legal_seen = set()

    for value in legal_indices:
        idx = int(value)

        if idx not in legal_seen:
            legal.append(idx)
            legal_seen.add(idx)

    minimum = max(0, int(min_count))
    maximum = max(0, int(max_count))

    assert minimum <= maximum, (
        "Official selection contract is invalid: "
        f"minCount={minimum}, maxCount={maximum}"
    )

    if maximum == 0:
        return []

    ranked_legal = []
    ranked_seen = set()

    for value in ranked_indices:
        idx = int(value)

        if (
            idx in legal_seen
            and idx not in ranked_seen
        ):
            ranked_legal.append(idx)
            ranked_seen.add(idx)

    result = ranked_legal[:maximum]

    # Fill from legal options only when the official simulator
    # requires additional selections.
    if len(result) < minimum:
        for idx in legal:
            if idx not in result:
                result.append(idx)

            if len(result) >= minimum:
                break

    assert len(result) <= maximum, (
        "Cardinality helper exceeded maxCount."
    )

    assert all(
        idx in legal_seen
        for idx in result
    ), (
        "Cardinality helper returned an illegal option."
    )

    assert len(result) == len(set(result)), (
        "Cardinality helper returned duplicate indices."
    )

    if len(legal) >= minimum:
        assert len(result) >= minimum, (
            "Cardinality helper failed to satisfy minCount "
            "despite sufficient legal options."
        )

    return result


