# =============================================================================
# 4. OFFICIAL SELECT-CONTRACT ADAPTER
# =============================================================================

def finalize_official_selection(
    observation,
    ranked_indices,
):
    """
    Apply the official observation.select cardinality contract to a ranked
    sequence of legal option indices.

    This function assumes ranked_indices refer to indices in select.options.
    """

    selection = getattr(
        observation,
        "select",
        None,
    )

    if selection is None:
        raise ValueError(
            "finalize_official_selection() received a deck-request "
            "observation rather than a normal selection context."
        )

    options = list(
        getattr(
            selection,
            "options",
            [],
        )
    )

    legal_indices = list(
        range(len(options))
    )

    min_count = int(
        getattr(
            selection,
            "minCount",
            1,
        )
    )

    max_count = int(
        getattr(
            selection,
            "maxCount",
            1,
        )
    )

    return enforce_official_cardinality(
        ranked_indices=ranked_indices,
        legal_indices=legal_indices,
        min_count=min_count,
        max_count=max_count,
    )


