entrypoint_source_18 = r'''
def _load_deck():
    import os

    deck_path = "deck.csv"

    if not os.path.exists(deck_path):
        deck_path = (
            "/kaggle_simulations/agent/deck.csv"
        )

    with open(
        deck_path,
        "r",
        encoding="utf-8",
    ) as file:
        values = [
            line.strip()
            for line in file
            if line.strip()
        ]

    deck = [
        int(value)
        for value in values
    ]

    if len(deck) != 60:
        raise RuntimeError(
            f"Expected 60-card deck; got {len(deck)}."
        )

    return deck


MY_DECK = _load_deck()


# Final Notebook 20 BattlePolicy has no constructor arguments.
# Supporting adapter/ranker logic uses the module-level repository.
POLICY = BattlePolicy()

def agent(obs_dict: dict) -> list[int]:
    observation = to_observation_class(
        obs_dict
    )

    # Initial deck request.
    if getattr(
        observation,
        "select",
        None,
    ) is None:
        return list(
            MY_DECK
        )

    selection = observation.select

    options = list(
        getattr(
            selection,
            "options",
            [],
        )
    )

    legal_indices = list(
        range(
            len(options)
        )
    )

    if not legal_indices:
        return []

    # Preserve Notebook 20 decision logic.
    decision = POLICY.decide(
        observation
    )

    primary_index = int(
        decision.option_index
    )

    # rank_legal_actions gives us the complete
    # source-proven ordering needed for multi-select.
    snapshot = adapt_observation(
        observation
    )

    ranking_result = rank_legal_actions(
        snapshot
    )

    ranked_indices = []

    for item in ranking_result:
        if isinstance(item, int):
            ranked_indices.append(
                int(item)
            )

        elif hasattr(
            item,
            "option_index",
        ):
            ranked_indices.append(
                int(
                    item.option_index
                )
            )

        elif isinstance(
            item,
            (tuple, list),
        ) and item:
            ranked_indices.append(
                int(
                    item[0]
                )
            )

    # Ensure Notebook 20's primary policy decision
    # remains first whenever it is legal.
    ranked_indices = (
        [primary_index]
        +
        ranked_indices
    )

    return enforce_official_cardinality(
        ranked_indices=ranked_indices,
        legal_indices=legal_indices,
        min_count=getattr(
            selection,
            "minCount",
            1,
        ),
        max_count=getattr(
            selection,
            "maxCount",
            1,
        ),
    )
'''


