def public_runtime_inventory_20(module):

    records = []

    for name in dir(module):

        if name.startswith("_"):
            continue

        value = getattr(
            module,
            name,
        )

        record = {
            "name": name,
            "type": type(value).__name__,
            "callable": callable(value),
        }

        if callable(value):

            try:
                record["signature"] = str(
                    inspect.signature(
                        value
                    )
                )
            except Exception:
                record["signature"] = "<unavailable>"

