from cg.game import (
    battle_start,
    battle_select,
    battle_finish,
)

# IMPORTANT:
# cg.game._get_battle_data() returns the JSON observation but
# does not expose SerialData.selectPlayer.
#
# We therefore read the selecting player from the official
# native SerialData structure itself.
from cg.sim import (
    Battle,
    lib,
)


def load_module(
    name,
    path,
):

    spec = (
        importlib.util
        .spec_from_file_location(
            name,
            path,
        )
    )

    if spec is None or spec.loader is None:

        raise RuntimeError(
            f"Could not create import specification for {path}"
        )

    module = (
        importlib.util
        .module_from_spec(
            spec
        )
    )

    spec.loader.exec_module(
        module
    )

    return module


def normalize_agent_result(
    result,
):

    if isinstance(
        result,
        int,
    ):

        return [
            int(result)
        ]

    if isinstance(
        result,
        tuple,
    ):

        result = list(
            result
        )

    if not isinstance(
        result,
        list,
    ):

        raise TypeError(
            "Agent result must be int or list[int]; "
            f"observed {type(result).__name__}"
        )

    if not all(
        isinstance(
            value,
            int,
        )
        for value
        in result
    ):

        raise TypeError(
            "Agent result contains non-integer values."
        )

    return [
        int(value)
        for value
        in result
    ]


def get_native_select_player():
    """
    Return the player currently required to make the official
    simulator selection.

    Source of truth:
        cg.sim.SerialData.selectPlayer

    We intentionally do NOT infer the selecting player from
    observation heuristics.
    """

    if (
        Battle.battle_ptr is None
        or
        Battle.battle_ptr == 0
    ):

        raise RuntimeError(
            "Battle pointer is unavailable."
        )

    serial_data = (
        lib.GetBattleData(
            Battle.battle_ptr
        )
    )

    player = int(
        serial_data.selectPlayer
    )

    if player not in (
        0,
        1,
    ):

        raise RuntimeError(
            "Official native simulator returned invalid "
            f"selectPlayer={player}."
        )

    return player


