    # Preserve safe fallback / primary policy choice.
    ranked_indices = (
        [primary_index]
        +
        ranked_indices
    )


    # --------------------------------------------------------
    # Official minCount / maxCount enforcement
    # --------------------------------------------------------

    return enforce_official_cardinality(
        ranked_indices=ranked_indices,
        legal_indices=legal_indices,
        min_count=min_count,
        max_count=max_count,
    )
