def load_module(name, path):
    """
    Load module using Python 3.13-safe import semantics.

    The module must be registered in sys.modules before
    exec_module() because @dataclass processing inspects
    sys.modules during class creation.
    """

    spec = importlib.util.spec_from_file_location(
        name,
        path,
    )

    if spec is None or spec.loader is None:
        raise RuntimeError(
            f"Cannot import module from {path}"
        )

    module = importlib.util.module_from_spec(
        spec
    )

    # Critical Python 3.13 fix for dataclass-decorated classes.
    sys.modules[name] = module

    try:

        spec.loader.exec_module(
            module
        )

    except Exception:

        # Remove partially initialized module if import fails.
        sys.modules.pop(
            name,
            None,
        )

        raise

    return module

def normalize_action(value):

    if isinstance(value, int):
        return [int(value)]

    if isinstance(value, tuple):
        value = list(value)

    if not isinstance(value, list):
        raise TypeError(
            "Agent output must be int or list[int]; "
            f"observed {type(value).__name__}"
        )

    if not all(
        isinstance(item, int)
        for item in value
    ):
        raise TypeError(
            "Agent output contains non-integer selection."
        )

    return [
        int(item)
        for item in value
    ]


