def decorated_node_start(node):
    """
    Return the first source line belonging to a top-level definition,
    including decorators such as @dataclass.
    """

    starts = [
        node.lineno
    ]

    for decorator in getattr(
        node,
        "decorator_list",
        [],
    ):
        starts.append(
            decorator.lineno
        )

    return min(
        starts
    )


def extract_closure_source_decorator_safe(
    source_text,
    tree,
    symbol_names,
):
    """
    Extract selected top-level classes/functions in original source order,
    preserving decorator lines.
    """

    source_lines = (
        source_text.splitlines()
    )

    selected_nodes = []

    for node in tree.body:

        if (
            isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                    ast.ClassDef,
                ),
            )
            and node.name in symbol_names
        ):

            selected_nodes.append(
                node
            )

    selected_nodes.sort(
        key=lambda node: decorated_node_start(
            node
        )
    )

    blocks = []

    for node in selected_nodes:

        start = decorated_node_start(
            node
        )

        end = getattr(
            node,
            "end_lineno",
            node.lineno,
        )

        blocks.append(
            "\n".join(
                source_lines[
                    start - 1:end
                ]
            )
        )

    return "\n\n".join(
        blocks
    )


