def decorated_classes(source):

    tree = ast.parse(
        source
    )

    records = []

    for node in tree.body:

        if isinstance(
            node,
            ast.ClassDef,
        ):

            decorators = []

            for decorator in (
                node.decorator_list
            ):

                if isinstance(
                    decorator,
                    ast.Name,
                ):

                    decorators.append(
                        decorator.id
                    )

                elif isinstance(
                    decorator,
                    ast.Attribute,
                ):

                    decorators.append(
                        decorator.attr
                    )

                else:

                    decorators.append(
                        ast.unparse(
                            decorator
                        )
                    )

            records.append(
                {
                    "class":
                        node.name,

                    "decorators":
                        decorators,
                }
            )

    return records


