def load_module(name, path):
    """
    Load a Python module from an explicit file path using
    standard import semantics.

    IMPORTANT:
    Register the module in sys.modules BEFORE exec_module().
    Python 3.13 dataclasses inspect sys.modules while class
    decorators are being evaluated.
    """

    spec = importlib.util.spec_from_file_location(
        name,
        path,
    )

    if spec is None or spec.loader is None:
        raise RuntimeError(
            f"Cannot import module from {path}"
        )

    module = importlib.util.module_from_spec(
        spec
    )

    # Required for @dataclass processing during module execution.
    sys.modules[name] = module

    try:

        spec.loader.exec_module(
            module
        )

    except Exception:

        # Do not leave a partially initialized module registered.
        sys.modules.pop(
            name,
            None,
        )

        raise

    return module


def normalize_action(value):

    if isinstance(value, int):
        return [int(value)]

    if isinstance(value, tuple):
        value = list(value)

    if not isinstance(value, list):
        raise TypeError(
            "Agent output must be int or list[int]; "
            f"observed {type(value).__name__}"
        )

    if not all(
        isinstance(item, int)
        for item in value
    ):
        raise TypeError(
            "Agent output contains non-integer selection."
        )

    return [
        int(item)
        for item in value
    ]


def native_select_player():

    if (
        Battle.battle_ptr is None
        or
        Battle.battle_ptr == 0
    ):
        raise RuntimeError(
            "Battle pointer unavailable."
        )

    serial_data = lib.GetBattleData(
        Battle.battle_ptr
    )

    player = int(
        serial_data.selectPlayer
    )

    if player not in (0, 1):
        raise RuntimeError(
            f"Invalid official selectPlayer={player}"
        )

    return player


def selection_contract(obs_dict):

    select_data = obs_dict.get(
        "select"
    )

    if not isinstance(
        select_data,
        dict,
    ):
        return {
            "minCount": 0,
            "maxCount": 0,
            "option_count": 0,
            "context": None,
            "type": None,
        }

    options = (
        select_data.get(
            "option"
        )
        or []
    )

    return {
        "minCount": int(
            select_data.get(
                "minCount",
                0,
            )
        ),
        "maxCount": int(
            select_data.get(
                "maxCount",
                0,
            )
        ),
        "option_count": len(
            options
        ),
        "context": select_data.get(
            "context"
        ),
        "type": select_data.get(
            "type"
        ),
    }


