# ------------------------------------------------------------
# 5. AST transformer:
#    remove official_lookup ONLY from adapt_card calls
# ------------------------------------------------------------

class AdaptCardOfficialLookupRemover(
    ast.NodeTransformer
):

    def __init__(self):
        self.repair_count = 0
        self.repaired_lines = []

    def visit_Call(self, node):
        node = self.generic_visit(node)

        called_name = None

        if isinstance(node.func, ast.Name):
            called_name = node.func.id

        elif isinstance(node.func, ast.Attribute):
            called_name = node.func.attr

        if called_name != "adapt_card":
            return node

        original_keywords = list(
            node.keywords
        )

        repaired_keywords = [
            keyword
            for keyword
            in original_keywords
            if keyword.arg != "official_lookup"
        ]

        removed_count = (
            len(original_keywords)
            -
            len(repaired_keywords)
        )

        if removed_count:
            self.repair_count += removed_count

            self.repaired_lines.append(
                getattr(
                    node,
                    "lineno",
                    None,
                )
            )

            node.keywords = repaired_keywords

        return node


