sys.path.insert(0, ROOT)

from cg.game import (
    battle_start,
    battle_select,
    battle_finish,
)

from cg.sim import (
    Battle,
    lib,
)

from cg.api import (
    to_observation_class,
)


def load_module(name, path):

    spec = importlib.util.spec_from_file_location(
        name,
        path,
    )

    if spec is None or spec.loader is None:
        raise RuntimeError(
            f"Cannot import module from {path}"
        )

    module = importlib.util.module_from_spec(
        spec
    )

    sys.modules[name] = module

    try:

        spec.loader.exec_module(
            module
        )

    except Exception:

        sys.modules.pop(
            name,
            None,
        )

        raise

    return module


def native_select_player():

    serial_data = lib.GetBattleData(
        Battle.battle_ptr
    )

    player = int(
        serial_data.selectPlayer
    )

    if player not in (0, 1):
        raise RuntimeError(
            f"Invalid selectPlayer={player}"
        )

    return player


def normalize_action(value):

    if isinstance(value, int):
        return [int(value)]

    if isinstance(value, tuple):
        value = list(value)

    if not isinstance(value, list):
        raise TypeError(
            f"Invalid agent output type: "
            f"{type(value).__name__}"
        )

    return [
        int(item)
        for item in value
    ]


