def module_bound_names_21k(
    tree,
):

    names = set()

    for node in tree.body:

        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
            ),
        ):

            names.add(
                node.name
            )

        elif isinstance(
            node,
            ast.Assign,
        ):

            for target in node.targets:

                if isinstance(
                    target,
                    ast.Name,
                ):

                    names.add(
                        target.id
                    )

        elif isinstance(
            node,
            ast.AnnAssign,
        ):

            if isinstance(
                node.target,
                ast.Name,
            ):

                names.add(
                    node.target.id
                )

        elif isinstance(
            node,
            ast.Import,
        ):

            for alias in node.names:

                names.add(
                    alias.asname
                    or
                    alias.name.split(
                        "."
                    )[0]
                )

        elif isinstance(
            node,
            ast.ImportFrom,
        ):

            for alias in node.names:

                names.add(
                    alias.asname
                    or
                    alias.name
                )

    return names


