import ast
import json


print("=" * 78)
print("NOTEBOOK 62 — CELL 21K-A")
print("PRECISE NOTEBOOK 19 'ranked' SCOPE / BINDING AUDIT")
print("=" * 78)


# ------------------------------------------------------------
# 1. Preconditions
# ------------------------------------------------------------

assert "CELL21J_STATUS" in globals()
assert CELL21J_STATUS["validation_status"] == "PASS"

assert "FINAL_MAIN_SOURCE_18" in globals()
assert "FINAL_MAIN_SOURCE_21H" in globals()

assert (
    FINAL_MAIN_SOURCE_18
    ==
    FINAL_MAIN_SOURCE_21H
), (
    "FINAL_MAIN_SOURCE_18 changed after Cell 21H. "
    "Do not continue until authoritative runtime is restored."
)

assert "nb19_script_text" in globals()

print("[OK] Cell 21J audit available.")
print("[OK] Cell 21H runtime remains authoritative.")
print("[OK] Notebook 19 source available.")
print("[OK] Audit is read-only.")
print("[OK] No submission files will be written.")


# ------------------------------------------------------------
# 2. Parse authoritative Notebook 19
# ------------------------------------------------------------

tree_21ka = ast.parse(
    nb19_script_text
)

source_lines_21ka = (
    nb19_script_text.splitlines()
)


# ------------------------------------------------------------
# 3. Build parent map
# ------------------------------------------------------------

parent_21ka = {}

for parent in ast.walk(tree_21ka):
    for child in ast.iter_child_nodes(parent):
        parent_21ka[child] = parent


def enclosing_scope_21ka(node):
    """
    Return nearest function/class scope containing node.
    If none exists, node is module-level.
    """

    current = node

    while current in parent_21ka:

        current = parent_21ka[current]

        if isinstance(
            current,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
                ast.ClassDef,
                ast.Lambda,
            ),
        ):
            return current

    return None


def scope_description_21ka(node):

    scope = enclosing_scope_21ka(node)

    if scope is None:
        return {
            "scope_type": "module",
            "scope_name": "<module>",
            "scope_line": 1,
        }

    if isinstance(scope, ast.Lambda):
        name = "<lambda>"
    else:
        name = getattr(
            scope,
            "name",
            "<unknown>",
        )

    return {
        "scope_type":
            type(scope).__name__,

        "scope_name":
            name,

        "scope_line":
            getattr(
                scope,
                "lineno",
                None,
            ),
    }


# ------------------------------------------------------------
# 4. Locate every Name('ranked')
# ------------------------------------------------------------

ranked_occurrences_21ka = []


for node in ast.walk(tree_21ka):

    if not (
        isinstance(node, ast.Name)
        and
        node.id == "ranked"
    ):
        continue

    context = type(node.ctx).__name__

    scope_info = (
        scope_description_21ka(node)
    )

    start = max(
        1,
        node.lineno - 3,
    )

    end = min(
        len(source_lines_21ka),
        node.lineno + 3,
    )

    snippet = "\n".join(
        f"{line_no:04d}: "
        f"{source_lines_21ka[line_no - 1]}"
        for line_no
        in range(
            start,
            end + 1,
        )
    )

    ranked_occurrences_21ka.append({
        "line":
            node.lineno,

        "column":
            node.col_offset,

        "context":
            context,

        **scope_info,

        "snippet":
            snippet,
    })


ranked_occurrences_21ka.sort(
    key=lambda item: (
        item["line"],
        item["column"],
    )
)


print()
print("=" * 78)
print("1. ALL 'ranked' OCCURRENCES")
print("=" * 78)

for item in ranked_occurrences_21ka:

    print()
    print(
        f"Line {item['line']} "
        f"[{item['context']}]"
    )

    print(
        "Scope:",
        f"{item['scope_type']} "
        f"{item['scope_name']} "
        f"(starts line "
        f"{item['scope_line']})"
    )

    print(item["snippet"])


# ------------------------------------------------------------
# 5. Separate stores and loads by actual lexical scope
# ------------------------------------------------------------

stores_21ka = [
    item
    for item
    in ranked_occurrences_21ka
    if item["context"] == "Store"
]

loads_21ka = [
    item
    for item
    in ranked_occurrences_21ka
    if item["context"] == "Load"
]


module_stores_21ka = [
    item
    for item
    in stores_21ka
    if item["scope_type"] == "module"
]

function_stores_21ka = [
    item
    for item
    in stores_21ka
    if item["scope_type"] != "module"
]


print()
print("=" * 78)
print("2. SCOPE CLASSIFICATION")
print("=" * 78)

print(
    "Total ranked stores:",
    len(stores_21ka),
)

print(
    "Module-level ranked stores:",
    len(module_stores_21ka),
)

print(
    "Function/class-local ranked stores:",
    len(function_stores_21ka),
)

print(
    "Total ranked loads:",
    len(loads_21ka),
)


if module_stores_21ka:

    print()
    print(
        "TRUE MODULE-LEVEL STORES:"
    )

    for item in module_stores_21ka:
        print(
            f"  line {item['line']}"
        )

else:

    print()
    print(
        "[OK] No true module-level "
        "'ranked' assignment exists."
    )


# ------------------------------------------------------------
# 6. Group uses by scope
# ------------------------------------------------------------

scope_groups_21ka = {}

for item in ranked_occurrences_21ka:

    key = (
        item["scope_type"],
        item["scope_name"],
        item["scope_line"],
    )

    scope_groups_21ka.setdefault(
        key,
        {
            "stores": [],
            "loads": [],
        },
    )

    if item["context"] == "Store":

        scope_groups_21ka[key][
            "stores"
        ].append(
            item["line"]
        )

    elif item["context"] == "Load":

        scope_groups_21ka[key][
            "loads"
        ].append(
            item["line"]
        )


print()
print("=" * 78)
print("3. PER-SCOPE BINDING SUMMARY")
print("=" * 78)


unbound_scopes_21ka = []


for key, data in sorted(
    scope_groups_21ka.items(),
    key=lambda pair:
        pair[0][2]
        if pair[0][2] is not None
        else -1,
):

    scope_type, scope_name, scope_line = key

    print()
    print(
        f"{scope_type} "
        f"{scope_name} "
        f"(line {scope_line})"
    )

    print(
        "  stores:",
        data["stores"],
    )

    print(
        "  loads:",
        data["loads"],
    )

    # A scope containing loads but no store may rely on
    # an outer/module binding.
    if (
        data["loads"]
        and
        not data["stores"]
    ):

        unbound_scopes_21ka.append({
            "scope_type":
                scope_type,

            "scope_name":
                scope_name,

            "scope_line":
                scope_line,

            "load_lines":
                data["loads"],
        })


# ------------------------------------------------------------
# 7. Inspect exact enclosing statements for stores
# ------------------------------------------------------------

print()
print("=" * 78)
print("4. STORE STATEMENT AUDIT")
print("=" * 78)


store_statement_types_21ka = []


for item in stores_21ka:

    matching_node = None

    for node in ast.walk(tree_21ka):

        if (
            isinstance(node, ast.Name)
            and
            node.id == "ranked"
            and
            isinstance(node.ctx, ast.Store)
            and
            node.lineno == item["line"]
            and
            node.col_offset == item["column"]
        ):

            matching_node = node
            break

    assert matching_node is not None

    current = matching_node

    statement = None

    while current in parent_21ka:

        current = parent_21ka[current]

        if isinstance(
            current,
            ast.stmt,
        ):
            statement = current
            break

    assert statement is not None

    statement_source = (
        ast.get_source_segment(
            nb19_script_text,
            statement,
        )
    )

    store_statement_types_21ka.append({
        "line":
            item["line"],

        "scope_type":
            item["scope_type"],

        "scope_name":
            item["scope_name"],

        "statement_type":
            type(statement).__name__,

        "statement":
            statement_source,
    })

    print()
    print(
        f"Store line {item['line']}"
    )

    print(
        "Scope:",
        item["scope_type"],
        item["scope_name"],
    )

    print(
        "Statement type:",
        type(statement).__name__,
    )

    print(statement_source)


