# ---------------------------------------------------------------------------
# 2. ENUM EXTRACTION HELPERS
# ---------------------------------------------------------------------------

def safe_int(value: Any):
    try:
        return int(value)
    except Exception:
        return None


def enum_members_from_class(cls: type) -> list[dict[str, Any]]:
    """
    Extract enum members from Python Enum/IntEnum classes without changing
    anything in the installed package.
    """
    rows = []

    try:
        members = getattr(cls, "__members__", {})
    except Exception:
        members = {}

    for name, member in members.items():
        raw_value = getattr(member, "value", member)

        rows.append(
            {
                "name": str(name),
                "value_repr": repr(raw_value),
                "value_int": safe_int(raw_value),
                "member_repr": repr(member),
            }
        )

    return rows


def protobuf_enum_values(obj: Any) -> list[dict[str, Any]]:
    """
    Attempt to inspect protobuf-style enum wrappers/descriptors.
    """
    rows = []

    descriptor = getattr(obj, "DESCRIPTOR", None)

    if descriptor is not None:
        values = getattr(descriptor, "values", None)

        if values:
            for value in values:
                rows.append(
                    {
                        "name": str(getattr(value, "name", "")),
                        "value_repr": repr(getattr(value, "number", None)),
                        "value_int": safe_int(getattr(value, "number", None)),
                        "member_repr": repr(value),
                    }
                )

    # Generated protobuf EnumTypeWrapper
    keys_method = getattr(obj, "keys", None)

    if callable(keys_method):
        try:
            for name in keys_method():
                try:
                    number = obj.Value(name)
                except Exception:
                    number = None

                row = {
                    "name": str(name),
                    "value_repr": repr(number),
                    "value_int": safe_int(number),
                    "member_repr": repr(number),
                }

                if row not in rows:
                    rows.append(row)
        except Exception:
            pass

    return rows


def inspect_enum_like_object(
    module_name: str,
    object_name: str,
    obj: Any,
) -> dict[str, Any] | None:

    rows = []

    if inspect.isclass(obj):
        try:
            if issubclass(obj, enum.Enum):
                rows.extend(enum_members_from_class(obj))
        except Exception:
            pass

    for row in protobuf_enum_values(obj):
        if row not in rows:
            rows.append(row)

    if not rows:
        return None

    return {
        "module": module_name,
        "object": object_name,
        "qualified_name": f"{module_name}.{object_name}",
        "members": rows,
    }


