# ---------------------------------------------------------------------------
# 1. HELPERS
# ---------------------------------------------------------------------------

def safe_signature(obj):
    try:
        return str(inspect.signature(obj))
    except Exception as exc:
        return f"<signature unavailable: {type(exc).__name__}: {exc}>"

def safe_source(obj):
    try:
        return inspect.getsource(obj)
    except Exception as exc:
        return f"<source unavailable: {type(exc).__name__}: {exc}>"

def safe_sourcefile(obj):
    try:
        return inspect.getsourcefile(obj)
    except Exception:
        return None

def class_structure(cls):
    out = {
        "repr": repr(cls),
        "module": getattr(cls, "__module__", None),
        "qualname": getattr(cls, "__qualname__", None),
        "signature": safe_signature(cls),
        "source_file": safe_sourcefile(cls),
        "annotations": {},
        "dataclass_fields": {},
        "namedtuple_fields": [],
        "slots": [],
        "class_dict_keys": [],
    }

    try:
        out["annotations"] = {
            str(k): repr(v)
            for k, v in getattr(cls, "__annotations__", {}).items()
        }
    except Exception:
        pass

    try:
        if dataclasses.is_dataclass(cls):
            out["dataclass_fields"] = {
                f.name: {
                    "type": repr(f.type),
                    "default": repr(f.default),
                }
                for f in dataclasses.fields(cls)
            }
    except Exception:
        pass

    try:
        fields = getattr(cls, "_fields", None)
        if fields:
            out["namedtuple_fields"] = list(fields)
    except Exception:
        pass

    try:
        slots = getattr(cls, "__slots__", None)
        if slots:
            if isinstance(slots, str):
                out["slots"] = [slots]
            else:
                out["slots"] = list(slots)
    except Exception:
        pass

    try:
        out["class_dict_keys"] = sorted(
            k for k in cls.__dict__.keys()
            if not k.startswith("__")
        )
    except Exception:
        pass

    return out

def enum_table(enum_cls):
    rows = []
    try:
        for member in enum_cls:
            rows.append({
                "name": member.name,
                "value": member.value,
                "repr": repr(member),
            })
    except Exception:
        pass
    return rows

def print_source_excerpt(title, source, patterns=None, context=4):
    print("\n" + "-" * 88)
    print(title)
    print("-" * 88)

    if source.startswith("<source unavailable"):
        print(source)
        return []

    lines = source.splitlines()

    if not patterns:
        for i, line in enumerate(lines, 1):
            print(f"{i:04d}: {line}")
        return list(range(1, len(lines) + 1))

    regexes = [re.compile(p, re.I) for p in patterns]

    hit_lines = []
    for i, line in enumerate(lines):
        if any(rx.search(line) for rx in regexes):
            hit_lines.append(i)

    if not hit_lines:
        print("No matching source lines.")
        return []

    show = set()
    for idx in hit_lines:
        for j in range(max(0, idx - context), min(len(lines), idx + context + 1)):
            show.add(j)

    previous = None
    for idx in sorted(show):
        if previous is not None and idx > previous + 1:
            print("      ...")
        print(f"{idx + 1:04d}: {lines[idx]}")
        previous = idx

    return [i + 1 for i in hit_lines]

