def node_source_21o(
    node,
):

    return "\n".join(
        runtime_lines_21o[
            node.lineno - 1:
            node.end_lineno
        ]
    )


def all_top_level_functions_21o(
    name,
):
    """
    Return all top-level function definitions for `name`
    in source order.
    """

    return [
        node
        for node
        in runtime_tree_21o.body
        if (
            isinstance(
                node,
                (
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            )
            and
            node.name
            ==
            name
        )
    ]


def effective_top_level_function_21o(
    name,
):
    """
    Python module semantics:
    later top-level definitions replace earlier definitions.

    Therefore the final source-order definition is effective.
    """

    matches = (
        all_top_level_functions_21o(
            name
        )
    )

    if not matches:
        return None

    return matches[-1]


