def effective_function_source_from_text_21q(
    text,
    name,
):

    tree = ast.parse(
        text
    )

    lines = (
        text.splitlines()
    )

    matches = [
        node
        for node
        in tree.body
        if (
            isinstance(
                node,
                ast.FunctionDef,
            )
            and
            node.name
            ==
            name
        )
    ]

    if not matches:
        return None

    node = matches[-1]

    return "\n".join(
        lines[
            node.lineno - 1:
            node.end_lineno
        ]
    )


