# =============================================================================
# HELPER FUNCTIONS
# =============================================================================

def sha256_path_21u(path: Path) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        for chunk in iter(
            lambda: handle.read(1024 * 1024),
            b"",
        ):

            digest.update(chunk)

    return digest.hexdigest()


def snapshot_directory_21u(root: Path) -> dict:

    snapshot = {}

    for path in sorted(root.rglob("*")):

        if not path.is_file():
            continue

        relative = str(
            path.relative_to(root)
        )

        snapshot[relative] = {
            "size": path.stat().st_size,
            "sha256": sha256_path_21u(path),
        }

    return snapshot


def parse_python_file_21u(path: Path) -> tuple[bool, str | None]:

    try:

        source = path.read_text(
            encoding="utf-8"
        )

        ast.parse(
            source,
            filename=str(path),
        )

        compile(
            source,
            str(path),
            "exec",
        )

        return True, None

    except Exception as exc:

        return False, (
            f"{type(exc).__name__}: {exc}"
        )


def find_function_names_21u(source: str) -> set[str]:

    tree = ast.parse(source)

    return {
        node.name
        for node in ast.walk(tree)
        if isinstance(
            node,
            (
                ast.FunctionDef,
                ast.AsyncFunctionDef,
            ),
        )
    }


