def is_enum_name_option_type_call_21u(
    node,
):

    if not isinstance(
        node,
        ast.Call,
    ):
        return False

    if not (
        isinstance(
            node.func,
            ast.Name,
        )
        and
        node.func.id
        ==
        "enum_name"
    ):
        return False

    if len(
        node.args
    ) != 1:
        return False

    argument = node.args[0]

    return (
        isinstance(
            argument,
            ast.Attribute,
        )
        and
        argument.attr
        ==
        "type"
        and
        isinstance(
            argument.value,
            ast.Name,
        )
        and
        argument.value.id
        ==
        "option"
    )


old_defective_nodes_21u = []


for node in ast.walk(
    main_tree_21u
):

    if isinstance(
        node,
        ast.Assign,
    ):

        target_is_option_type = any(
            isinstance(
                target,
                ast.Name,
            )
            and
            target.id
            ==
            "option_type"

            for target
            in node.targets
        )

        if (
            target_is_option_type
            and
            is_enum_name_option_type_call_21u(
                node.value
            )
        ):

            old_defective_nodes_21u.append(
                node
            )


    elif isinstance(
        node,
        ast.keyword,
    ):

        if (
            node.arg
            ==
            "option_type"
            and
            is_enum_name_option_type_call_21u(
                node.value
            )
        ):

            old_defective_nodes_21u.append(
                node
            )


