# =============================================================================
# HELPER
# =============================================================================

def sha256_21uc2(path: Path) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        for chunk in iter(
            lambda: handle.read(1024 * 1024),
            b"",
        ):
            digest.update(chunk)

    return digest.hexdigest()


def import_records_21uc2(path: Path) -> list[dict]:

    source = path.read_text(
        encoding="utf-8"
    )

    tree = ast.parse(
        source,
        filename=str(path),
    )

    records = []

    for node in tree.body:

        if isinstance(
            node,
            ast.Import,
        ):

            records.append(
                {
                    "line": node.lineno,
                    "kind": "import",
                    "module": None,
                    "level": 0,
                    "names": [
                        alias.name
                        for alias
                        in node.names
                    ],
                }
            )

        elif isinstance(
            node,
            ast.ImportFrom,
        ):

            records.append(
                {
                    "line": node.lineno,
                    "kind": "from",
                    "module": node.module,
                    "level": node.level,
                    "names": [
                        alias.name
                        for alias
                        in node.names
                    ],
                }
            )

    return records


