def sha256_file_21ud2(path: Path) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        for chunk in iter(
            lambda: handle.read(1024 * 1024),
            b"",
        ):
            digest.update(chunk)

    return digest.hexdigest()


def source_snapshot_21ud2(root: Path) -> dict:

    """
    Snapshot deployment source/content while deliberately excluding
    Python-generated cache/bytecode artifacts.
    """

    snapshot = {}

    for path in sorted(root.rglob("*")):

        if not path.is_file():
            continue

        if "__pycache__" in path.parts:
            continue

        if path.suffix.lower() in {
            ".pyc",
            ".pyo",
        }:
            continue

        relative = str(
            path.relative_to(root)
        )

        snapshot[relative] = {
            "size": path.stat().st_size,
            "sha256": sha256_file_21ud2(path),
        }

    return snapshot


