# =============================================================================
# HELPERS
# =============================================================================

def sha256_file_21v(
    path: Path,
) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        for chunk in iter(
            lambda: handle.read(
                1024 * 1024
            ),
            b"",
        ):
            digest.update(chunk)

    return digest.hexdigest()


def package_snapshot_21v(
    root: Path,
) -> dict:

    snapshot = {}

    for path in sorted(
        root.rglob("*")
    ):

        if not path.is_file():
            continue

        relative = (
            path.relative_to(root)
            .as_posix()
        )

        snapshot[
            relative
        ] = {
            "size":
                path.stat().st_size,

            "sha256":
                sha256_file_21v(
                    path
                ),
        }

    return snapshot


def python_validate_21v(
    path: Path,
) -> tuple[bool, str | None]:

    try:

        source = path.read_text(
            encoding="utf-8"
        )

        ast.parse(
            source,
            filename=str(path),
        )

        compile(
            source,
            str(path),
            "exec",
        )

        return True, None

    except Exception as exc:

        return (
            False,
            f"{type(exc).__name__}: {exc}",
        )


