# =============================================================================
# HELPERS
# =============================================================================

def sha256_file_21w(
    path: Path,
) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        for chunk in iter(
            lambda: handle.read(
                1024 * 1024
            ),
            b"",
        ):

            digest.update(
                chunk
            )

    return digest.hexdigest()


def sha256_bytes_21w(
    data: bytes,
) -> str:

    return hashlib.sha256(
        data
    ).hexdigest()


def snapshot_nonzip_package_21w(
    root: Path,
) -> dict:

    snapshot = {}

    for path in sorted(
        root.rglob("*")
    ):

        if not path.is_file():
            continue

        relative = (
            path.relative_to(root)
            .as_posix()
        )

        if relative.lower().endswith(
            ".zip"
        ):
            continue

        snapshot[
            relative
        ] = {
            "size":
                path.stat().st_size,

            "sha256":
                sha256_file_21w(
                    path
                ),
        }

    return snapshot


