# =============================================================================
# NOTEBOOK 62 — CELL 21X
# FINAL ARCHIVE EXTRACTION SMOKE TEST + NOTEBOOK 62 COMPLETION CERTIFICATE
# =============================================================================
#
# PURPOSE
# -------
# Perform the final independent validation of the exact archive produced by
# Cell 21W.
#
# This cell:
#   - requires Cell 21W PASS
#   - freezes the final ZIP hash
#   - extracts the ZIP to an isolated temporary directory
#   - verifies exact archive/extraction manifest
#   - verifies every extracted file against the validated Cell 21V manifest
#   - verifies main.py and required deployment dependencies
#   - parses/compiles all extracted Python files
#   - checks for forbidden cache/bytecode/temp artifacts
#   - verifies no training/retraining calls
#   - verifies the real submission and final ZIP remain unchanged
#   - verifies the certified model remains unchanged
#   - issues the Notebook 62 completion certificate
#
# IMPORTANT
# ---------
# This cell is READ-ONLY with respect to the real submission.
# No submission files are written.
# No archive is rebuilt.
# No model is modified.
# No retraining occurs.
#
# =============================================================================

from __future__ import annotations

import ast
import hashlib
import json
import shutil
import tempfile
import zipfile
from pathlib import Path


print("=" * 88)
print("NOTEBOOK 62 — CELL 21X")
print("FINAL ARCHIVE EXTRACTION SMOKE TEST + NOTEBOOK 62 COMPLETION CERTIFICATE")
print("=" * 88)


# =============================================================================
# HELPERS
# =============================================================================

def sha256_file_21x(path: Path) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        for chunk in iter(
            lambda: handle.read(1024 * 1024),
            b"",
        ):
            digest.update(chunk)

    return digest.hexdigest()


def snapshot_files_21x(root: Path) -> dict:

    snapshot = {}

    for path in sorted(root.rglob("*")):

        if not path.is_file():
            continue

        relative = (
            path.relative_to(root)
            .as_posix()
        )

        snapshot[relative] = {
            "size": path.stat().st_size,
            "sha256": sha256_file_21x(path),
        }

    return snapshot


def validate_python_21x(path: Path):

    try:

        source = path.read_text(
            encoding="utf-8"
        )

        ast.parse(
            source,
            filename=str(path),
        )

        compile(
            source,
            str(path),
            "exec",
        )

        return True, None

    except Exception as exc:

        return (
            False,
            f"{type(exc).__name__}: {exc}",
        )


