# =============================================================================
# 14. TRAINING / RETRAINING AUDIT
# =============================================================================

print()
print("=" * 88)
print("14. TRAINING / RETRAINING AUDIT")
print("=" * 88)


training_names_21x = {
    "fit",
    "partial_fit",
    "fit_transform",
}


training_calls_21x = []


for path in extracted_python_files_21x:

    source = path.read_text(
        encoding="utf-8"
    )


    tree = ast.parse(
        source,
        filename=str(path),
    )


    for node in ast.walk(tree):

        if not isinstance(
            node,
            ast.Call,
        ):
            continue


        call_name = None


        if isinstance(
            node.func,
            ast.Name,
        ):

            call_name = (
                node.func.id
            )


        elif isinstance(
            node.func,
            ast.Attribute,
        ):

            call_name = (
                node.func.attr
            )


        if call_name in training_names_21x:

            training_calls_21x.append(
                {
                    "file":
                        path.relative_to(
                            extraction_root_21x
                        ).as_posix(),

                    "line":
                        node.lineno,

                    "call":
                        call_name,
                }
            )


assert not training_calls_21x


print(
    "Training calls:",
    training_calls_21x,
)


